import { Icon } from "@/registry/p1/internal/icons";
import "./comparison-table.css";

export interface ComparisonRow {
  feature: string;
  c1: string;
  c2: string;
  c3: string;
  c4: string;
}
export interface ComparisonTableProps {
  eyebrow: string;
  heading: string;
  subtitle: string;
  columns: string;
  featured: "none" | "1" | "2" | "3" | "4";
  rows: ComparisonRow[];
}

const splitLines = (s: string) =>
  String(s || "")
    .split("\n")
    .map((x) => x.trim())
    .filter(Boolean);

const ROW_KEYS = ["c1", "c2", "c3", "c4"] as const satisfies readonly (keyof ComparisonRow)[];
function rowKeyFor(ci: number): keyof ComparisonRow {
  switch (ci) {
    case 0: return ROW_KEYS[0];
    case 1: return ROW_KEYS[1];
    case 2: return ROW_KEYS[2];
    default: return ROW_KEYS[3];
  }
}

const CMP_YES = ["yes", "true", "✓", "✔", "check", "included", "all", "y", "∞"];
const CMP_NO = ["no", "false", "✗", "✕", "x", "none", "n"];

function CmpCell({ v }: { v: string }) {
  const s = String(v == null ? "" : v).trim();
  const l = s.toLowerCase();
  if (s === "" || s === "-" || s === "—") return <span className="p1-comparison__dash">—</span>;
  if (CMP_YES.includes(l)) return <Icon name="check" strokeWidth={2.6} className="p1-comparison__check" />;
  if (CMP_NO.includes(l)) return <Icon name="x" strokeWidth={2.4} className="p1-comparison__cross" />;
  return <span className="p1-comparison__val">{s}</span>;
}

export function ComparisonTableRender({
  eyebrow,
  heading,
  subtitle,
  columns,
  featured,
  rows,
}: ComparisonTableProps) {
  const plans = splitLines(columns).slice(0, 4);
  const hot = ({ none: -1, "1": 0, "2": 1, "3": 2, "4": 3 } as Record<string, number>)[featured] ?? -1;

  return (
    <div className="p1-comparison-table p1-block">
      <div className="p1-comparison__inner">
        <div className="p1-comparison__header">
          {eyebrow && <p className="p1-comparison__eyebrow">{eyebrow}</p>}
          {heading && <h2 className="p1-comparison__heading">{heading}</h2>}
          {subtitle && <p className="p1-comparison__subtitle">{subtitle}</p>}
        </div>

        <div className="p1-comparison__table-wrap">
          <table className="p1-comparison__table">
            <thead>
              <tr>
                <th className="p1-comparison__feature-col">Features</th>
                {plans.map((pl, i) => (
                  <th key={i} className="p1-comparison__col-head" data-hot={i === hot ? "true" : undefined}>
                    {pl}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {(rows || []).map((row, ri) => (
                <tr key={ri}>
                  <td className="p1-comparison__row-label">{row.feature}</td>
                  {plans.map((_, ci) => (
                    <td key={ci} className="p1-comparison__cell" data-hot={ci === hot ? "true" : undefined}>
                      <CmpCell v={row[rowKeyFor(ci)]} />
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="p1-comparison__cards">
          {plans.map((pl, ci) => (
            <div key={ci} className="p1-comparison__card" data-hot={ci === hot ? "true" : undefined}>
              <div className="p1-comparison__card-head">{pl}</div>
              {(rows || []).map((row, ri) => (
                <div key={ri} className="p1-comparison__card-row">
                  <span className="p1-comparison__card-label">{row.feature}</span>
                  <span className="p1-comparison__card-val">
                    <CmpCell v={row[rowKeyFor(ci)]} />
                  </span>
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { ComparisonTableRender, type ComparisonTableProps, type ComparisonRow } from "./comparison-table";
export type { ComparisonTableProps, ComparisonRow };

export const ComparisonTableBlock: ComponentConfig<ComparisonTableProps> = {
  fields: {
    eyebrow: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Short label above the heading. 1–3 words. Leave blank to omit." },
    },
    heading: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Table heading. Under 8 words." },
    },
    subtitle: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "1 sentence below the heading." },
    },
    columns: {
      type: "text" as const,
      ai: { instructions: "Plan names separated by newlines. Max 4. E.g. Starter\nTeam\nEnterprise." },
    },
    featured: {
      type: "select" as const,
      options: [
        { label: "None", value: "none" },
        { label: "Column 1", value: "1" },
        { label: "Column 2", value: "2" },
        { label: "Column 3", value: "3" },
        { label: "Column 4", value: "4" },
      ],
    },
    rows: {
      type: "array",
      arrayFields: {
        feature: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "Feature name." },
        },
        c1: { type: "text" as const, ai: { instructions: "Value for column 1. Use yes/no or a short value." } },
        c2: { type: "text" as const, ai: { instructions: "Value for column 2." } },
        c3: { type: "text" as const, ai: { instructions: "Value for column 3." } },
        c4: {
          type: "text" as const,
          ai: { instructions: "Value for column 4. Leave blank if fewer than 4 plans." },
        },
      },
      defaultItemProps: { feature: "Feature", c1: "yes", c2: "yes", c3: "yes", c4: "" },
      getItemSummary: (item: ComparisonRow) => item.feature || "Feature",
    },
  },
  defaultProps: {
    eyebrow: "Compare",
    heading: "Find the plan that fits.",
    subtitle: "Every plan includes the core WebOps workflow.",
    columns: "Starter\nTeam\nEnterprise",
    featured: "2",
    rows: [
      { feature: "Projects", c1: "1", c2: "10", c3: "Unlimited", c4: "" },
      { feature: "Multidev environments", c1: "no", c2: "yes", c3: "yes", c4: "" },
      { feature: "Role-based access", c1: "no", c2: "yes", c3: "yes", c4: "" },
      { feature: "SSO & audit logs", c1: "no", c2: "no", c3: "yes", c4: "" },
      { feature: "Support", c1: "Community", c2: "Priority", c3: "Dedicated CSM", c4: "" },
    ],
  },
  render: ComparisonTableRender,
};

export const meta = defineMeta({
  title: 'Comparison Table',
  description: 'Feature comparison table with up to 4 named columns and checkmark/text rows; use for pricing or product capability comparisons.',
  categories: ["convert"],
  published: true,
  registryDependencies: ["@p1/tokens","@p1/internal-icons"],
});

.p1-comparison-table {
  padding-block: var(--p1-space-xl);
  padding-inline: var(--p1-space-lg);
}

.p1-comparison__inner {
  margin-inline: auto;
  max-inline-size: var(--p1-container-wide);
}

.p1-comparison__header {
  margin-block-end: var(--p1-space-xl);
  text-align: center;
}

.p1-comparison__eyebrow {
  color: var(--p1-accent);
  font-size: var(--p1-text-xl);
  font-style: italic;
  margin-block-end: var(--p1-space-sm);
}

.p1-comparison__heading {
  font-size: var(--p1-text-3xl);
  font-weight: var(--p1-weight-bold);
  letter-spacing: -0.02em;
  color: var(--p1-fg-default);
}
@media (width >= 48rem) {
  .p1-comparison__heading { font-size: var(--p1-text-4xl); }
}

.p1-comparison__subtitle {
  color: var(--p1-fg-muted);
  margin-block-start: var(--p1-space-sm);
}

/* Wide table — hidden on narrow */
.p1-comparison__table-wrap { display: none; overflow-x: auto; }
@media (width >= 48rem) { .p1-comparison__table-wrap { display: block; } }

.p1-comparison__table {
  border-collapse: separate;
  border-spacing: 0;
  inline-size: 100%;
  table-layout: fixed;
}

.p1-comparison__feature-col {
  color: var(--p1-fg-muted);
  font-size: var(--p1-text-xs);
  font-weight: var(--p1-weight-bold);
  inline-size: 34%;
  letter-spacing: 0.04em;
  padding: var(--p1-space-md);
  text-align: start;
  text-transform: uppercase;
  vertical-align: bottom;
}

.p1-comparison__col-head {
  border-block-end: 2px solid var(--p1-border);
  color: var(--p1-fg-default);
  font-size: var(--p1-text-lg);
  font-weight: var(--p1-weight-bold);
  padding: var(--p1-space-md);
  text-align: center;
}
.p1-comparison__col-head[data-hot="true"] {
  background-color: var(--p1-accent);
  border-block-end: none;
  border-start-end-radius: var(--p1-radius-card);
  border-start-start-radius: var(--p1-radius-card);
  color: var(--p1-fg-inverse);
}

.p1-comparison__row-label {
  border-block-end: 1px solid var(--p1-border-subtle);
  color: var(--p1-fg-default);
  font-size: var(--p1-text-sm);
  font-weight: var(--p1-weight-semibold);
  padding: var(--p1-space-md);
}

.p1-comparison__cell {
  border-block-end: 1px solid var(--p1-border-subtle);
  padding: var(--p1-space-md);
  text-align: center;
}
.p1-comparison__cell[data-hot="true"] {
  background-color: color-mix(in oklch, var(--p1-accent) 6%, transparent);
}

.p1-comparison__check {
  block-size: 1.25rem;
  color: var(--p1-success, oklch(0.6 0.15 150));
  display: block;
  inline-size: 1.25rem;
  margin-inline: auto;
}
.p1-comparison__cell[data-hot="true"] .p1-comparison__check { color: var(--p1-accent); }
.p1-comparison__col-head[data-hot="true"] .p1-comparison__check { color: var(--p1-fg-inverse); }

.p1-comparison__cross {
  block-size: 1.125rem;
  color: var(--p1-border);
  display: block;
  inline-size: 1.125rem;
  margin-inline: auto;
}

.p1-comparison__dash { color: var(--p1-border); }

.p1-comparison__val {
  color: var(--p1-fg-default);
  font-size: var(--p1-text-sm);
  font-weight: var(--p1-weight-semibold);
}

/* Narrow stacked cards — hidden on wide */
.p1-comparison__cards { display: grid; gap: var(--p1-space-md); }
@media (width >= 48rem) { .p1-comparison__cards { display: none; } }

.p1-comparison__card {
  border: 1px solid var(--p1-border);
  border-radius: var(--p1-radius-card);
  overflow: hidden;
}
.p1-comparison__card[data-hot="true"] {
  border: 2px solid var(--p1-accent);
}

.p1-comparison__card-head {
  background-color: var(--p1-surface-subtle);
  color: var(--p1-fg-default);
  font-size: var(--p1-text-lg);
  font-weight: var(--p1-weight-bold);
  padding: var(--p1-space-md);
}
.p1-comparison__card[data-hot="true"] .p1-comparison__card-head {
  background-color: var(--p1-accent);
  color: var(--p1-fg-inverse);
}

.p1-comparison__card-row {
  align-items: center;
  border-block-start: 1px solid var(--p1-border-subtle);
  display: flex;
  gap: var(--p1-space-sm);
  justify-content: space-between;
  padding-block: var(--p1-space-sm);
  padding-inline: var(--p1-space-md);
}

.p1-comparison__card-label {
  color: var(--p1-fg-muted);
  font-size: var(--p1-text-sm);
}

.p1-comparison__card-val { flex-shrink: 0; }

.p1-comparison__card[data-hot="true"] .p1-comparison__check { color: var(--p1-accent); }

